builder.Services.AddAuthorizationBuilder()
    .AddPolicy("CanReadInvoices", p => p.RequireClaim("scope", "invoices:read"));

app.MapGet("/invoices/{id:int}", async (int id, IAuthorizationService authz,
                                        ClaimsPrincipal user) =>
{
    var invoice = await db.Invoices.FindAsync(id);
    var decision = await authz.AuthorizeAsync(user, invoice, "CanReadInvoices");
    return decision.Succeeded ? Results.Ok(invoice) : Results.Forbid();
});
